+.brand-mark { width: 30px; height: 30px; border-radius: 9px; background: var(--green); color: white; display: grid; place-items: center; transform: rotate(-3deg); }
+.close-nav { display: none !important; }
+.add-button { margin: 31px 2px 20px; height: 43px; border: 0; border-radius: 10px; background: var(--green); color: white; display: flex; align-items: center; justify-content: center; gap: 8px; font-weight: 600; cursor: pointer; box-shadow: 0 5px 14px rgba(47, 99, 73, .14); transition: .2s ease; }
+.add-button:hover, .quick-add:hover, .primary-button:hover { background: var(--green-dark); transform: translateY(-1px); }
+.nav-list { display: grid; gap: 3px; }
+.nav-item { border: 0; background: transparent; height: 39px; border-radius: 9px; display: flex; align-items: center; gap: 11px; padding: 0 11px; color: #5f625c; cursor: pointer; text-align: left; font-size: 14px; }
+.nav-item span:nth-child(2) { flex: 1; }
+.nav-item:hover { background: rgba(255,255,255,.55); color: var(--ink); }
+.nav-item.active { background: #fff; color: #262823; font-weight: 600; box-shadow: 0 1px 3px rgba(20,20,15,.05); }
+.nav-count { color: #969890; font-size: 12px; font-weight: 500; }
+.sidebar-section { margin-top: 27px; }
+.section-label { display: flex; align-items: center; justify-content: space-between; color: #92948d; text-transform: uppercase; letter-spacing: .09em; font-size: 10px; font-weight: 700; padding: 0 10px 9px; }
+.section-label button { border: 0; background: transparent; color: #7b7e77; display: grid; place-items: center; cursor: pointer; }
+.tag-nav { display: grid; gap: 2px; }
