@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Manrope:wght@600;700;800&display=swap');

:root {
  font-family: 'DM Sans', sans-serif;
  color: #20211f;
  background: #f7f7f5;
  font-synthesis: none;
  --ink: #20211f;
  --muted: #74766f;
  --soft: #f1f1ee;
  --line: #e6e6e1;
  --green: #2f6349;
  --green-dark: #234c38;
}

* { box-sizing: border-box; }
body { margin: 0; min-width: 320px; min-height: 100vh; background: #f7f7f5; }
button, input, textarea, select { font: inherit; }
button { color: inherit; }
button, a { -webkit-tap-highlight-color: transparent; }

.app-shell { min-height: 100vh; }
.sidebar { position: fixed; inset: 0 auto 0 0; width: 250px; background: #f0f0ed; border-right: 1px solid #e1e1dd; padding: 28px 18px 18px; display: flex; flex-direction: column; z-index: 30; }
.sidebar-top { display: flex; align-items: center; justify-content: space-between; padding: 0 8px; }
.brand { display: flex; align-items: center; gap: 10px; font: 800 18px 'Manrope', sans-serif; letter-spacing: -0.5px; }
.brand-mark { width: 30px; height: 30px; border-radius: 9px; background: var(--green); color: white; display: grid; place-items: center; transform: rotate(-3deg); }
.close-nav { display: none !important; }
.add-button { margin: 31px 2px 20px; height: 43px; border: 0; border-radius: 10px; background: var(--green); color: white; display: flex; align-items: center; justify-content: center; gap: 8px; font-weight: 600; cursor: pointer; box-shadow: 0 5px 14px rgba(47, 99, 73, .14); transition: .2s ease; }
.add-button:hover, .quick-add:hover, .primary-button:hover { background: var(--green-dark); transform: translateY(-1px); }
.nav-list { display: grid; gap: 3px; }
.nav-item { border: 0; background: transparent; height: 39px; border-radius: 9px; display: flex; align-items: center; gap: 11px; padding: 0 11px; color: #5f625c; cursor: pointer; text-align: left; font-size: 14px; }
.nav-item span:nth-child(2) { flex: 1; }
.nav-item:hover { background: rgba(255,255,255,.55); color: var(--ink); }
.nav-item.active { background: #fff; color: #262823; font-weight: 600; box-shadow: 0 1px 3px rgba(20,20,15,.05); }
.nav-count { color: #969890; font-size: 12px; font-weight: 500; }
.sidebar-section { margin-top: 27px; }
.section-label { display: flex; align-items: center; justify-content: space-between; color: #92948d; text-transform: uppercase; letter-spacing: .09em; font-size: 10px; font-weight: 700; padding: 0 10px 9px; }
.section-label button { border: 0; background: transparent; color: #7b7e77; display: grid; place-items: center; cursor: pointer; }
.tag-nav { display: grid; gap: 2px; }
.tag-nav button { width: 100%; border: 0; background: transparent; display: flex; gap: 10px; align-items: center; padding: 9px 11px; border-radius: 9px; font-size: 13px; color: #686a64; cursor: pointer; }
.tag-nav button:hover, .tag-nav button.active { background: rgba(255,255,255,.6); color: var(--ink); }
.tag-nav button span:nth-child(2) { flex: 1; text-align: left; }
.tag-dot { width: 7px; height: 7px; border-radius: 50%; background: #758dce; }
.dot-1 { background: #d18d5f; } .dot-2 { background: #6aa88d; } .dot-3 { background: #a17abc; } .dot-4 { background: #d06d7e; } .dot-5 { background: #c4a343; }
.sidebar-footer { margin-top: auto; }
.sidebar-footer > button { border: 0; background: transparent; display: flex; gap: 11px; align-items: center; color: #74766f; padding: 10px; cursor: pointer; font-size: 13px; }
.user-card { border-top: 1px solid #deded9; margin-top: 10px; padding: 18px 8px 4px; display: grid; grid-template-columns: 35px 1fr auto; align-items: center; gap: 10px; }
.avatar { width: 35px; height: 35px; border-radius: 50%; background: #d9c8b5; color: #704c32; display: grid; place-items: center; font-size: 11px; font-weight: 700; }
.user-card strong, .user-card span { display: block; }
.user-card strong { font-size: 12px; }
.user-card span { color: #91938d; font-size: 10px; margin-top: 2px; }
.user-card > svg { color: #8d8f89; }

.main-content { padding-left: 250px; min-height: 100vh; }
.topbar { height: 74px; border-bottom: 1px solid var(--line); display: flex; align-items: center; padding: 0 42px; position: sticky; top: 0; background: rgba(247,247,245,.9); backdrop-filter: blur(14px); z-index: 15; }
.search-wrap { width: min(490px, 55vw); height: 40px; display: flex; align-items: center; gap: 10px; color: #8b8d86; }
.search-wrap input { flex: 1; min-width: 0; border: 0; outline: 0; background: transparent; font-size: 14px; color: var(--ink); }
.search-wrap input::placeholder { color: #969891; }
kbd { background: #eeeeeb; border: 1px solid #dfdfda; border-radius: 6px; padding: 3px 7px; color: #8c8e87; font: 11px 'DM Sans'; }
.quick-add { margin-left: auto; height: 38px; padding: 0 16px; border: 0; border-radius: 9px; color: white; background: var(--green); display: flex; align-items: center; gap: 7px; cursor: pointer; font-weight: 600; font-size: 13px; transition: .2s ease; }
.menu-button, .mobile-logo { display: none !important; }
.icon-button { width: 36px; height: 36px; border: 0; border-radius: 9px; display: grid; place-items: center; background: transparent; cursor: pointer; color: #6d6f69; }
.icon-button:hover { background: #ecece8; color: #252621; }
.content-wrap { max-width: 1240px; padding: 48px 48px 70px; margin: 0 auto; }
.page-heading { display: flex; align-items: flex-end; justify-content: space-between; gap: 24px; }
.eyebrow { color: var(--green); text-transform: uppercase; letter-spacing: .1em; font-size: 10px; font-weight: 700; display: flex; align-items: center; gap: 5px; margin-bottom: 9px; }
.page-heading h1 { font: 700 clamp(31px, 3vw, 42px) 'Manrope', sans-serif; letter-spacing: -1.7px; margin: 0; line-height: 1.1; }
.page-heading p { color: var(--muted); margin: 9px 0 0; font-size: 14px; }
.bookmark-total { display: flex; flex-direction: column; align-items: flex-end; padding-bottom: 3px; }
.bookmark-total strong { font: 700 25px 'Manrope'; line-height: 1; }
.bookmark-total span { font-size: 11px; color: #969890; margin-top: 4px; }
.toolbar { display: flex; justify-content: space-between; align-items: center; margin: 41px 0 17px; }
.results-label { color: #8b8d86; font-size: 12px; }
.results-label strong { color: #4b4d47; }
.toolbar-actions { display: flex; align-items: center; gap: 11px; }
.sort-control { height: 34px; display: flex; align-items: center; gap: 4px; border: 1px solid #deded9; border-radius: 8px; padding: 0 8px 0 10px; color: #8b8d86; font-size: 11px; background: #fafaf8; }
.sort-control select { appearance: none; border: 0; background: transparent; outline: 0; color: #474943; font-size: 11px; padding: 0 12px 0 2px; cursor: pointer; }
.sort-control svg { margin-left: -13px; pointer-events: none; }
.view-toggle { padding: 3px; border: 1px solid #deded9; background: #ecece8; border-radius: 8px; display: flex; }
.view-toggle button { width: 29px; height: 26px; border: 0; background: transparent; display: grid; place-items: center; border-radius: 5px; color: #969890; cursor: pointer; }
.view-toggle button.active { background: white; color: #484a44; box-shadow: 0 1px 3px rgba(20,20,15,.1); }
.bookmarks-grid { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 14px; }
.bookmark-card { min-width: 0; height: 232px; padding: 19px 19px 15px; border: 1px solid #e2e2dd; background: #fdfdfb; border-radius: 13px; display: flex; flex-direction: column; box-shadow: 0 1px 1px rgba(30,30,20,.02); transition: transform .2s ease, box-shadow .2s ease, border-color .2s ease; }
.bookmark-card:hover { transform: translateY(-2px); border-color: #d4d5ce; box-shadow: 0 9px 24px rgba(33,35,29,.06); }
.card-main { min-height: 0; }
.card-heading { display: grid; grid-template-columns: 37px minmax(0,1fr) auto; gap: 11px; align-items: start; }
.site-icon { width: 37px; height: 37px; color: white; border-radius: 10px; display: grid; place-items: center; font-size: 13px; font-weight: 700; box-shadow: inset 0 0 0 1px rgba(0,0,0,.07); }
.card-title-wrap { min-width: 0; padding-top: 1px; }
.card-title-wrap h3 { margin: 0 0 4px; font-size: 13.5px; font-weight: 600; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.card-title-wrap a { display: flex; align-items: center; gap: 4px; color: #969890; font-size: 10.5px; text-decoration: none; width: fit-content; }
.card-title-wrap a:hover { color: var(--green); }
.card-actions { display: flex; gap: 1px; margin: -3px -6px 0 0; }
.favorite-button, .more-button { width: 28px; height: 28px; border: 0; border-radius: 7px; display: grid; place-items: center; background: transparent; color: #aaaca5; cursor: pointer; }
.favorite-button:hover, .more-button:hover { color: #555850; background: #f0f0ed; }
.favorite-button.on { color: #d45d63; }
.menu-wrap { position: relative; }
.context-menu { position: absolute; right: 0; top: 31px; width: 130px; background: white; border: 1px solid var(--line); border-radius: 9px; padding: 5px; box-shadow: 0 10px 30px rgba(20,20,15,.12); z-index: 10; }
.context-menu button { width: 100%; display: flex; align-items: center; gap: 8px; border: 0; background: transparent; border-radius: 6px; padding: 7px 8px; font-size: 11px; cursor: pointer; }
.context-menu button:hover { background: #f3f3ef; }
.context-menu .danger { color: #bd4c50; }
.description { color: #6f716a; font-size: 12px; line-height: 1.55; margin: 20px 1px 0; display: -webkit-box; -webkit-box-orient: vertical; -webkit-line-clamp: 3; overflow: hidden; }
.card-footer { margin-top: auto; padding-top: 14px; border-top: 1px solid #eeeeea; display: flex; align-items: center; justify-content: space-between; gap: 8px; }
.card-tags { display: flex; gap: 5px; overflow: hidden; }
.card-tags span { background: #f0f0ec; color: #72756d; padding: 4px 7px; border-radius: 5px; font-size: 9.5px; white-space: nowrap; }
.saved-time { color: #a0a29b; font-size: 9.5px; white-space: nowrap; }
.bookmarks-grid.list-view { grid-template-columns: 1fr; }
.bookmark-card.list-card { height: auto; min-height: 125px; display: grid; grid-template-columns: 1fr auto; column-gap: 28px; }
.list-card .description { max-width: 650px; margin-top: 12px; -webkit-line-clamp: 2; }
.list-card .card-footer { border: 0; border-left: 1px solid #eee; padding: 4px 0 4px 24px; margin: 0; min-width: 175px; flex-direction: column; justify-content: center; align-items: flex-start; }
.list-card .card-tags { flex-wrap: wrap; }
.empty-state { margin-top: 16px; height: 350px; display: flex; flex-direction: column; align-items: center; justify-content: center; border: 1px dashed #d8d8d2; border-radius: 14px; text-align: center; }
.empty-icon { width: 50px; height: 50px; border-radius: 14px; background: #e9eee9; color: var(--green); display: grid; place-items: center; }
.empty-state h2 { font: 700 20px 'Manrope'; margin: 16px 0 5px; }
.empty-state p { color: var(--muted); font-size: 13px; margin: 0 0 20px; }

.modal-backdrop { position: fixed; inset: 0; background: rgba(31,32,29,.48); backdrop-filter: blur(4px); display: grid; place-items: center; padding: 20px; z-index: 50; animation: fade .18s ease; }
.modal { width: min(100%, 510px); background: #fbfbf9; border-radius: 17px; box-shadow: 0 25px 70px rgba(20,20,15,.22); padding: 25px; animation: rise .24s ease; }
.modal-header { display: flex; align-items: flex-start; justify-content: space-between; margin-bottom: 24px; }
.modal-header h2 { margin: 0; font: 700 24px 'Manrope'; letter-spacing: -.6px; }
.modal form { display: grid; gap: 16px; }
.modal label { font-size: 11px; color: #50524c; font-weight: 600; }
.modal label > span { float: right; color: #9b9d96; font-weight: 400; }
.modal input, .modal textarea { margin-top: 7px; width: 100%; border: 1px solid #deded9; outline: 0; border-radius: 9px; background: white; padding: 11px 12px; color: var(--ink); font-size: 13px; resize: vertical; transition: border .2s, box-shadow .2s; }
.modal input:focus, .modal textarea:focus { border-color: #69907a; box-shadow: 0 0 0 3px rgba(47,99,73,.1); }
.modal input::placeholder, .modal textarea::placeholder { color: #aaa; }
.modal-actions { display: flex; justify-content: flex-end; gap: 9px; margin-top: 7px; }
.primary-button, .secondary-button { height: 40px; padding: 0 16px; border-radius: 9px; display: inline-flex; align-items: center; justify-content: center; gap: 7px; cursor: pointer; font-size: 12px; font-weight: 600; transition: .2s ease; }
.primary-button { border: 0; background: var(--green); color: white; }
.secondary-button { background: white; border: 1px solid #deded9; }
.secondary-button:hover { background: #f1f1ed; }
.toast { position: fixed; left: 50%; bottom: 28px; transform: translateX(-50%); color: white; background: #242621; padding: 10px 15px 10px 10px; border-radius: 10px; display: flex; align-items: center; gap: 9px; font-size: 12px; z-index: 80; box-shadow: 0 10px 30px rgba(20,20,15,.25); animation: toastIn .25s ease; }
.toast span { width: 23px; height: 23px; border-radius: 50%; display: grid; place-items: center; background: #49775d; }
.mobile-scrim { display: none; }

@keyframes fade { from { opacity: 0; } }
@keyframes rise { from { opacity: 0; transform: translateY(10px) scale(.98); } }
@keyframes toastIn { from { opacity: 0; transform: translate(-50%, 8px); } }

@media (max-width: 1040px) {
  .bookmarks-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .content-wrap { padding-left: 36px; padding-right: 36px; }
  .topbar { padding: 0 32px; }
}

@media (max-width: 760px) {
  .sidebar { transform: translateX(-100%); transition: transform .25s ease; box-shadow: 15px 0 40px rgba(20,20,15,.1); }
  .sidebar.open { transform: translateX(0); }
  .close-nav { display: grid !important; }
  .mobile-scrim { display: block; position: fixed; inset: 0; background: rgba(25,26,23,.3); opacity: 0; pointer-events: none; transition: opacity .2s; z-index: 29; }
  .mobile-scrim.visible { opacity: 1; pointer-events: auto; }
  .main-content { padding-left: 0; }
  .topbar { height: 66px; padding: 0 18px; gap: 10px; }
  .menu-button { display: grid !important; flex: 0 0 auto; }
  .mobile-logo { display: block !important; }
  .mobile-logo .brand > span { display: none; }
  .mobile-logo .brand-mark { width: 29px; height: 29px; }
  .search-wrap { width: auto; flex: 1; margin-left: 2px; }
  .search-wrap kbd { display: none; }
  .quick-add { width: 38px; padding: 0; justify-content: center; }
  .quick-add span { display: none; }
  .content-wrap { padding: 34px 20px 50px; }
  .page-heading { align-items: flex-start; }
  .bookmark-total { display: none; }
  .toolbar { margin-top: 31px; }
